export function shuffle(a,random=Math.random){const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;}
export function cleanChat(text){return String(text).replace(/^[^:：\n]{1,30}[:：]\s*(?=[“"「])/,'');}
export function createContest(random=Math.random){const seconds=18+Math.floor(random()*11);const names=[['네온크루','하루빛'],['오로라팀','달소미'],['별숲크루','루미온'],['구름연합','구름단'],['모래별팀','별하온'],['푸른파도','파도링']];return {seconds,opponents:shuffle(names,random).map(([crew,name],i)=>({crew,name,id:i+1,rate:1.6+i*.5+random()*.25,phase:random()*6}))};}
export function contestRows(contest,time,ups){return [{id:0,name:'큐티섹시',crew:'버블란',up:ups},...contest.opponents.map(o=>({...o,up:Math.floor(Math.max(0,Math.min(time,contest.seconds)*o.rate+Math.sin(time*.7+o.phase)*2-2))}))].sort((a,b)=>b.up-a.up||b.id-a.id);}
export function contestOutcome(contest,ups){const rows=contestRows(contest,contest.seconds,ups);const rank=rows.findIndex(x=>x.id===0)+1;return {rows,rank,qualified:rank<=3,ups,score:rank<=3?1-(rank-1)*.1:Math.max(.1,.55-rank*.05)};}
